def two_col(items, fs=34):
    cells = ''.join(f'<div data-build-in="pop {k + 1}" style="display:flex;flex-direction:row;gap:14px;align-items:center;background:#FFF8EA;border-radius:22px;padding:10px 20px">' + P(f'{k + 1}', 38, '#B0782A', True, True) + P(t, fs, '#1F2A3C', False, False, 'right', 'flex:1') + '</div>' for k, t in enumerate(items))
    return f'<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;width:100%">{cells}</div>'

